def number_existing_customers(apps, schema_editor):
    """Customers registered so far bought retail, so each gets a client number in the order they were registered."""
    Counterparty = apps.get_model("foundation", "SyntheticCounterparty")
    with schema_editor.connection.cursor() as cursor:
        for customer in Counterparty.objects.filter(party_type="customer", client_number__isnull=True).order_by("created_at", "pk"):
            cursor.execute("SELECT nextval('foundation_client_number_seq')")
            customer.client_number = f"C{cursor.fetchone()[0]:06d}"
            customer.save(update_fields=["client_number"])


